#FEL script to plot the Free Energy Landscape from the FEL_dPCA.csv file generated by dpca_pipeline.py"
#Author: Menzi Sikakane
""" 
Plot the 2D/3D Free Energy Landscape (FEL) from a dPCA output CSV
(as generated by dpca_pipeline.py), detect energy basins (local minima),
and export a summary table of basin energies and relative stabilities.
 
Inputs
------
A CSV file with at least three columns:
    - PC1       : first dPCA/PCA component
    - PC2       : second dPCA/PCA component
    - delta_G   : free energy value at each (PC1, PC2) grid point
 
Outputs
-------
    <CONDITION>_basin_summary.csv   Table of basin coordinates and energies
    FEL_2D_clean.png                2D contour plot of the energy surface
    FEL_basins_clean.png            2D contour plot with top 5 basins labeled
    FEL_3D_standard.png             3D surface plot (standard orientation)
    FEL_3D_volcano.png              3D surface plot (z-axis inverted) 
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.ticker import FormatStrFormatter
from scipy.ndimage import gaussian_filter, minimum_filter, label

FEL_CSV = "_FEL_dPCA.csv"
COL_PC1 = "PC1"
COL_PC2 = "PC2"
COL_G   = "delta_G"
SIGMA = 3.0 # Gaussian smoothing strength applied to the energy surface (higher = smoother)
MIN_DISTANCE = 2 # size of the neighbourhood window used when searching for local minima (basins)
N_LEVELS = 25 # number of contour levels/colour bands used in the plots
CONDITION = "" # label used in plot titles and output filenames (e.g. "WT", "Mutant")
df = pd.read_csv(FEL_CSV)
pivot = df.pivot_table(index=COL_PC2, columns=COL_PC1, values=COL_G) # reshape into a 2D grid: rows=PC2, columns=PC1, values=delta_G

x = pivot.columns.values
y = pivot.index.values
Z = pivot.values

Z[np.isnan(Z)] = np.nanmax(Z)
Z = gaussian_filter(Z, sigma=SIGMA)
Z -= np.min(Z)

X, Y = np.meshgrid(x, y)

neighborhood = np.ones((MIN_DISTANCE*2+1, MIN_DISTANCE*2+1))
local_min = (Z == minimum_filter(Z, footprint=neighborhood))
labeled, num_features = label(local_min)

print(f" Detected basins: {num_features}")
minima = []
for i in range(1, num_features + 1):
    coords = np.where(labeled == i)
    z_vals = Z[coords]
    idx = np.argmin(z_vals)
    y_idx = coords[0][idx]
    x_idx = coords[1][idx]
    minima.append((x[x_idx], y[y_idx], Z[y_idx, x_idx]))

minima = sorted(minima, key=lambda m: m[2])

print("\n Basin Energies (kJ/mol)")
for i, m in enumerate(minima):
    print(f"Basin {i+1}: PC1={m[0]:.3f}, PC2={m[1]:.3f}, ΔG={m[2]:.3f}")

print("\n ΔΔG relative to global minimum")
g0 = minima[0][2]

for i, m in enumerate(minima):
    ddg = m[2] - g0
    print(f"Basin {i+1}: ΔΔG = {ddg:.3f} kJ/mol")

# CSV summary 
summary_rows = []
for i, m in enumerate(minima):
    summary_rows.append({
        "Basin":      f"B{i+1}",
        "PC1":        round(m[0], 3),
        "PC2":        round(m[1], 3),
        "dG_kJ_mol":  round(m[2], 3),
        "ddG_kJ_mol": round(m[2] - g0, 3),
    })

summary_df = pd.DataFrame(summary_rows)
summary_csv = f"{CONDITION}_basin_summary.csv"
summary_df.to_csv(summary_csv, index=False)
print(f"\n Basin summary saved to: {summary_csv}")
print(summary_df.to_string(index=False))

g_min = 0.0
g_max = np.percentile(Z, 99)

fig1 = plt.figure(figsize=(7, 6))
ax1 = fig1.add_subplot(111)

cf = ax1.contourf(X, Y, Z, levels=N_LEVELS, cmap="jet",
                  vmin=g_min, vmax=g_max)

ax1.contour(X, Y, Z, levels=N_LEVELS,
            colors="k", linewidths=0.3, alpha=0.4)

ax1.set_title(f"{CONDITION} - 2D FEL (Clean)", fontweight="bold")
ax1.set_xlabel("PC1")
ax1.set_ylabel("PC2")

fig1.colorbar(cf, ax=ax1, label="ΔG (kJ/mol)", format="%.2f")
fig1.savefig("FEL_2D_clean.png", dpi=800, bbox_inches="tight")

fig2 = plt.figure(figsize=(7, 6))
ax2 = fig2.add_subplot(111)

cf2 = ax2.contourf(X, Y, Z, levels=N_LEVELS, cmap="jet",
                   vmin=g_min, vmax=g_max)

ax2.contour(X, Y, Z, levels=N_LEVELS,
            colors="k", linewidths=0.3, alpha=0.3)

for i, (px, py, pz) in enumerate(minima[:5]):
    ax2.scatter(px, py, s=60, edgecolor="black", linewidth=0.5)
    ax2.text(px + 0.2, py + 0.2, f"B{i+1}",
             fontsize=9, fontweight="bold",
             color="white")

ax2.set_title(f"{CONDITION} - FEL with Basins", fontweight="bold")
ax2.set_xlabel("PC1")
ax2.set_ylabel("PC2")

fig2.colorbar(cf2, ax=ax2, label="ΔG (kJ/mol)", format="%.2f")
fig2.savefig("FEL_basins_clean.png", dpi=800, bbox_inches="tight")

fig3 = plt.figure(figsize=(7, 6))
ax3 = fig3.add_subplot(111, projection="3d")

surf3 = ax3.plot_surface(
    X, Y, Z,
    cmap="jet",
    linewidth=0,
    antialiased=True,
    alpha=0.92,
    vmin=g_min,
    vmax=g_max, 
)

ax3.set_xlabel("PC1")
ax3.set_ylabel("PC2")
ax3.set_zlabel("ΔG (kJ/mol)")
ax3.zaxis.set_major_formatter(FormatStrFormatter('%.2f'))
ax3.set_title(f"{CONDITION} - 3D FEL (Standard)", fontweight="bold")
ax3.view_init(elev=30, azim=45)

fig3.colorbar(surf3, ax=ax3, shrink=0.6, label="ΔG (kJ/mol)", format="%.2f")
fig3.savefig("FEL_3D_standard.png", dpi=800, bbox_inches="tight")

fig4 = plt.figure(figsize=(7, 6))
ax4 = fig4.add_subplot(111, projection="3d")

surf4 = ax4.plot_surface(
    X, Y, Z,
    cmap="jet",
    linewidth=0,
    antialiased=True,
    alpha=0.92,
    vmin=g_min,
    vmax=g_max
)

ax4.invert_zaxis()

ax4.set_xlabel("PC1")
ax4.set_ylabel("PC2")
ax4.set_zlabel("ΔG (kJ/mol)")
ax4.zaxis.set_major_formatter(FormatStrFormatter('%.2f'))
ax4.set_title(f"{CONDITION} - 3D FEL (Volcano)", fontweight="bold")
ax4.view_init(elev=20, azim=45)

fig4.colorbar(surf4, ax=ax4, shrink=0.6, label="ΔG (kJ/mol)", format="%.2f")
fig4.savefig("FEL_3D_volcano.png", dpi=800, bbox_inches="tight")
plt.show()